ALTER TABLE public.gyms ADD COLUMN deletion_note text NOT NULL DEFAULT '', ADD COLUMN deletion_history jsonb NOT NULL DEFAULT '[]'::jsonb;
CREATE OR REPLACE FUNCTION public.set_gym_deleted(g uuid, deleted boolean, note text DEFAULT '') RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE x public.gyms; BEGIN IF NOT public.is_super_admin() THEN RAISE EXCEPTION 'Administrator access required'; END IF; SELECT * INTO x FROM public.gyms WHERE id=g FOR UPDATE; IF x.id IS NULL THEN RAISE EXCEPTION 'Gym unavailable'; END IF; IF deleted THEN IF x.deleted_at IS NOT NULL THEN RAISE EXCEPTION 'Gym is already deleted'; END IF; UPDATE public.gyms SET deleted_at=now(),deletion_note=left(coalesce(note,''),1000),deletion_history=deletion_history || jsonb_build_array(jsonb_build_object('action','deleted','at',now(),'note',left(coalesce(note,''),1000),'adminId',auth.uid())) WHERE id=g; ELSE IF x.deleted_at IS NULL THEN RAISE EXCEPTION 'Gym is not deleted'; END IF; IF EXISTS(SELECT 1 FROM public.profiles WHERE id=x.owner_id AND disabled_at IS NOT NULL) THEN RAISE EXCEPTION 'Owner account was separately deactivated. Restore the account before restoring this gym.'; END IF; UPDATE public.gyms SET deleted_at=NULL,deletion_history=deletion_history || jsonb_build_array(jsonb_build_object('action','restored','at',now(),'note',x.deletion_note,'adminId',auth.uid())) WHERE id=g; UPDATE public.owner_requests SET status='Approved',decided_at=now(),decision_by=auth.uid() WHERE gym_id=g AND status IS DISTINCT FROM 'Approved'; END IF; END $$;
REVOKE ALL ON FUNCTION public.set_gym_deleted(uuid,boolean,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.set_gym_deleted(uuid,boolean,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.owner_gate_state() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.owner_requests; g public.gyms; BEGIN SELECT * INTO r FROM public.owner_requests WHERE user_id=auth.uid() ORDER BY created_at DESC LIMIT 1; SELECT * INTO g FROM public.gyms WHERE id=r.gym_id; IF g.id IS NULL THEN SELECT * INTO g FROM public.gyms WHERE owner_id=auth.uid() ORDER BY created_at LIMIT 1; END IF; RETURN jsonb_build_object('gymId',g.id,'deleted',g.deleted_at IS NOT NULL OR EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND disabled_at IS NOT NULL),'deletionNote',coalesce(g.deletion_note,''),'frozen',g.frozen_at IS NOT NULL,'freezeNote',coalesce(g.freeze_note,''),'requestStatus',r.status,'plan',r.plan,'gymName',coalesce(g.name,r.gym_name),'trialStartedAt',r.trial_started_at,'trialEndsAt',r.trial_started_at+interval '1 hour','now',now()); END $$;